const pros = await sel('clientes_maestro', 'select=id,nombre,departamento,departamentos_activos,vendedor_asignado_id&macro_estado=eq.Prospecto');
for (const c of pros.filter(esWaterCli).filter(esDePrueba)) {
  const u = ctx.users.find((x) => x.id === c.vendedor_asignado_id && !x.is_suspended);
  if (u) add(u, 'prospecto:' + c.id, `🆕 *${c.nombre}*: ¿la Aplicación de Crédito fue *aceptada* o *rechazada*? (si fue rechazada, dime el motivo)`);
}
let ps = (await sel('proyectos_dinamicos', 'select=id,cliente_id,fase_id,responsable_id,tecnico_id,fecha_cierre&pipeline_id=eq.pip_water&fase_id=not.is.null'))
  .filter((p) => sigueAbierto(p, ctx));
if (ps.length) await nombresClientes(ctx, ps.map((p) => p.cliente_id));
ps = ps.filter((p) => proyDePrueba(p, ctx));
if (ps.length) {
  await cargarInstalaciones(ctx, ps);
  const resp = await sel('respuestas_dinamicas', `select=proyecto_id,campo_id,valor&proyecto_id=${inList(ps.map((p) => p.id))}`);
  for (const p of ps) {
    const linea = lineaPendiente(p, ctx, resp);
    if (linea) encargadosAutorizados(ctx.F[p.fase_id], p, ctx).forEach((u) => add(u, `proy:${p.id}:${p.fase_id}`, linea));
  }
}
// Día de la instalación: recordatorio al técnico (una vez, antes de la hora)
const deHoy = ps.filter((p) => p.fase_id === FASE_CERT && p.tecnico_id && momentoInstalacion(ctx.INST[p.id]) === 'hoy_antes' && !reciente(`hoy|${p.id}`, DIA));
const avisosHoy = [];
if (deHoy.length) {
  const dirs = Object.fromEntries((await sel('clientes_maestro', `select=id,direccion&id=${inList(deHoy.map((p) => p.cliente_id))}`)).map((c) => [c.id, c.direccion]));
  const porTec = {};
  deHoy.forEach((p) => { const t = ctx.users.find((u) => String(u.id) === String(p.tecnico_id) && !u.is_suspended); if (t) (porTec[t.id] = porTec[t.id] || { t, items: [] }).items.push(p); });
  for (const { t, items } of Object.values(porTec)) {
    const lineas = items.map((p) => `📅 ${ctx.INST[p.id].hora || 'hoy'} · *${ctx.N[p.cliente_id] || 'Cliente'}*${dirs[p.cliente_id] ? '\n   📍 ' + dirs[p.cliente_id] : ''}`);
    const text = `${horaFL < 12 ? 'Buenos días' : 'Buenas tardes'} ${t.nombre.trim()} ${horaFL < 12 ? '☀️' : '🌤️'}, hoy tienes ${items.length === 1 ? 'esta instalación' : 'estas instalaciones'} de Renew Water:\n\n${lineas.join('\n')}\n\nA la hora de cada instalación te mando el *Certificado de Instalación* para que lo completes de una vez.`;
    const enviado = SEND && (await sendSafe(norm(t.telefono), text));
    if (enviado) items.forEach((p) => (sd.reg[`hoy|${p.id}`] = new Date().toISOString()));
    avisosHoy.push({ json: { para: t.nombre.trim(), recordatorio: 'dia_de_instalacion', enviado, simulacion: !SEND, mensaje: text } });
  }
}

// A la hora de la instalación: el Certificado de Instalación al técnico para que lo complete de una vez
const aLaHora = ps.filter((p) => p.fase_id === FASE_CERT && p.tecnico_id && momentoInstalacion(ctx.INST[p.id]) === 'en_curso'
  && !sd.reg[`cert_hora|${p.id}`] && !(sd.cert[p.id] && sd.cert[p.id]._firmaUrl));
if (aLaHora.length) {
  const dirs = Object.fromEntries((await sel('clientes_maestro', `select=id,direccion&id=${inList(aLaHora.map((p) => p.cliente_id))}`)).map((c) => [c.id, c.direccion]));
  for (const p of aLaHora) {
    const t = ctx.users.find((u) => String(u.id) === String(p.tecnico_id) && !u.is_suspended);
    if (!t) continue;
    const cli = ctx.N[p.cliente_id] || 'Cliente';
    const prog = ctx.INST[p.id].equipos || {};
    const eqs = [prog.casa && 'Sistema para toda la casa', prog.osmosis && 'Ósmosis inversa', prog.pozo && 'Sistema de pozo'].filter(Boolean).join(', ');
    const text = [`📋 ${t.nombre.trim()}, ya es la hora de la instalación de *${cli}*${dirs[p.cliente_id] ? `\n📍 ${dirs[p.cliente_id]}` : ''}`, '',
      'Aquí tienes el *Certificado de Instalación* para que lo completes de una vez:', '',
      eqs ? `💧 *Equipos instalados* (según el representante): ${eqs}.` : '💧 ¿Qué *equipos* instalaste? (sistema para toda la casa / ósmosis inversa / pozo)', '',
      eqs ? 'Cuando termines, responde *SI* y se lo mando al cliente para que lo firme. Si cambió algún equipo, dímelo.' : 'Con eso armo el documento y se lo mando al cliente para que lo firme.'].join('\n');
    const enviado = SEND && (await sendSafe(norm(t.telefono), text));
    if (enviado) {
      sd.reg[`cert_hora|${p.id}`] = new Date().toISOString();
      // Borrador listo con los equipos: su respuesta va directo a este cliente
      if (!sd.cert[p.id]) sd.cert[p.id] = { equipos: Object.fromEntries(['casa', 'osmosis', 'pozo'].filter((k) => prog[k]).map((k) => [k, true])), _owner: t.id, _confirmando: !!eqs };
      sd.active[t.id] = p.id;
    }
    avisosHoy.push({ json: { para: t.nombre.trim(), recordatorio: 'certificado_a_la_hora', enviado, simulacion: !SEND, mensaje: text } });
  }
}

// Lo que ya se resolvió deja de contar
Object.keys(sd.cnt).forEach((k) => { if (!vivos.has(k)) { delete sd.cnt[k]; delete sd.reg[k]; } });

// 2) Recordatorio a cada persona, cada vez más firme
const out = [...avisosHoy];
const escalarMgr = {}, escalarAdm = {}; // destinatario -> líneas
for (const { u, items } of Object.values(porUsuario)) {
  if (await estaPausado(norm(u.telefono))) { out.push({ json: { para: u.nombre.trim(), pausado: true, enviado: false } }); continue; } // lo atiende una persona: ni recordar ni escalar
  const veces = Math.max(...items.map((x) => sd.cnt[x.k] || 0));
  const text = `${encabezadoRecordatorio(u.nombre.trim(), veces)}\n\n${listaCorta(items.map((x) => x.line))}\n\n${veces >= 2 ? 'Si ya lo hiciste en la app, avísame por aquí para actualizarlo. ' : ''}Respóndeme por aquí con texto o fotos (escribe el nombre del cliente en cada mensaje).`;
  let enviado = false;
  if (SEND) enviado = await sendSafe(norm(u.telefono), text);
  if (enviado) items.forEach((x) => { sd.cnt[x.k] = (sd.cnt[x.k] || 0) + 1; sd.reg[x.k] = new Date().toISOString(); });
  out.push({ json: { para: u.nombre.trim(), telefono: norm(u.telefono), avisos: veces + 1, enviado, simulacion: !SEND, mensaje: text } });

  // Escalamiento (los managers y admins solo reciben clientes que pueden ver)
  const atrasados = items.filter((x) => (sd.cnt[x.k] || 0) + (SEND ? 0 : 1) >= 3);
  if (!atrasados.length) continue;
  const quien = `${u.nombre.trim()} ${(u.apellido || '').trim()}`.trim();
  ctx.users.filter((m) => !m.is_suspended && m.id !== u.id && alcanceDe(m).manager && alcanceDe(m).equipo.includes(String(u.id)))
    .forEach((m) => { (escalarMgr[m.id] = escalarMgr[m.id] || { m, lines: [] }).lines.push(`• *${quien}* (${atrasados.length}): ${atrasados.map((x) => x.line.replace(/^\S+\s*/, '').split(':')[0]).join(', ')}`); });
  const muyAtrasados = items.filter((x) => (sd.cnt[x.k] || 0) + (SEND ? 0 : 1) >= 6);
  if (muyAtrasados.length) ctx.users.filter((a) => !a.is_suspended && a.id !== u.id && alcanceDe(a).admin)
    .forEach((a) => { (escalarAdm[a.id] = escalarAdm[a.id] || { a, lines: [] }).lines.push(`• ${quien}: ${muyAtrasados.length} pendiente(s) con 6+ avisos`); });
}

for (const { m, lines } of Object.values(escalarMgr)) {
  const k = `esc_mgr|${m.id}`;
  if (reciente(k, DIA)) continue;
  const text = `Hola ${m.nombre.trim()} 👋, te aviso como Manager de Venta: estas personas de tu equipo llevan 3 o más recordatorios sin pasarme los datos:\n\n${listaCorta(lines, 10)}\n\n¿Me ayudas a que me los manden hoy? 🙏`;
  const enviado = SEND && (await sendSafe(norm(m.telefono), text));
  if (enviado) sd.reg[k] = new Date().toISOString();
  out.push({ json: { para: m.nombre.trim(), escalamiento: 'manager', enviado, simulacion: !SEND, mensaje: text } });
}
for (const { a, lines } of Object.values(escalarAdm)) {
  const k = `esc_adm|${a.id}`;
  if (reciente(k, DIA)) continue;
  const text = `Hola ${a.nombre.trim()} 👋, resumen de pendientes atrasados en Renew Water:\n\n${listaCorta(lines, 15)}\n\nEl detalle está en la app.`;
  const enviado = SEND && (await sendSafe(norm(a.telefono), text));
  if (enviado) sd.reg[k] = new Date().toISOString();
  out.push({ json: { para: a.nombre.trim(), escalamiento: 'admin', enviado, simulacion: !SEND, mensaje: text } });
}
return out.length ? out : [{ json: { resultado: 'Nada pendiente (o ya se recordó en las últimas 4 h)' } }];
